def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Opposite-edge bars are matching solid segments. Markers aligned with either
    # segment project onto the corresponding offset in the other segment.
    for axis in (0, 1):  # 0: top/bottom bars; 1: left/right bars
        length, fixed = (w, h) if axis == 0 else (h, w)
        bars = []
        for edge in (0, fixed - 1):
            vals = [grid[edge][i] if axis == 0 else grid[i][edge] for i in range(length)]
            inds = [i for i, v in enumerate(vals) if v != bg]
            if (len(inds) >= 2 and inds == list(range(inds[0], inds[-1] + 1))
                    and len({vals[i] for i in inds}) == 1):
                bars.append((edge, inds[0], inds[-1], vals[inds[0]]))
        if len(bars) != 2 or bars[0][3] != bars[1][3]:
            continue
        bars.sort(key=lambda item: item[0])
        (edge_a, start_a, end_a, bar_color), (edge_b, start_b, end_b, _) = bars

        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and grid[r][c] != bar_color]
        for r, c, color in markers:
            pos = c if axis == 0 else r
            if start_a <= pos <= end_a:
                source_edge, source_start, target_start, target_end = edge_a, start_a, start_b, end_b
            elif start_b <= pos <= end_b:
                source_edge, source_start, target_start, target_end = edge_b, start_b, start_a, end_a
            else:
                continue
            mapped = target_start + pos - source_start
            if mapped > target_end:
                continue

            if axis == 0:
                # Ray from marker to its bar, plus a full parallel projected line.
                lo, hi = sorted((r, source_edge))
                for rr in range(lo + 1, hi):
                    if out[rr][c] == bg:
                        out[rr][c] = color
                for rr in range(h):
                    if out[rr][mapped] == bg:
                        out[rr][mapped] = color
            else:
                lo, hi = sorted((c, source_edge))
                for cc in range(lo + 1, hi):
                    if out[r][cc] == bg:
                        out[r][cc] = color
                for cc in range(w):
                    if out[mapped][cc] == bg:
                        out[mapped][cc] = color
            out[r][c] = 4
        return out
    return out
